// Classify Mailjet Event API events into two independent effects:
//   reason    (non-empty) -> add the address to the suppression list
//   newStatus (non-empty) -> advance the contact's email_status
//
// Mailjet is SEND-ONLY: it emits sent/open/click/bounce/blocked/spam/unsub
// but NEVER a reply, so there is no 'replied' path here (that KPI has no
// Mailjet source without a separate inbound-parse setup). Contacts are
// matched by the CustomID we stamp on every send ('outreach-contact-<id>');
// suppression is global and email-keyed. Mailjet may batch events into an
// array, so emit one item per event. Status writes never move a contact
// backwards (see the SQL): 'sent_email' only resolves a contact stuck at
// 'sending', so at-most-one-send holds.
const raw = $json.body ?? $json;
const events = Array.isArray(raw) ? raw : [raw];

return events.map((ev) => {
  const type = String(ev.event ?? '').toLowerCase();
  const email = String(ev.email ?? '').trim().toLowerCase();
  const customId = String(ev.CustomID ?? ev.custom_id ?? '').trim();
  const m = customId.match(/(\d+)\s*$/);
  const contactId = m ? m[1] : '';
  const hardBounce = ev.hard_bounce === true
    || String(ev.hard_bounce).toLowerCase() === 'true';

  let reason = '';      // -> suppression insert
  let newStatus = '';   // -> contacts.email_status
  let eventType = '';

  if (type === 'unsub')        { reason = 'unsubscribed';   eventType = 'suppression_added'; }
  else if (type === 'spam')    { reason = 'spam_complaint'; eventType = 'spam_suppressed'; }
  else if (type === 'blocked') { reason = 'blocked';        eventType = 'blocked_suppressed'; }
  else if (type === 'bounce' && hardBounce) {
    reason = 'hard_bounce'; newStatus = 'bounced'; eventType = 'bounce_suppressed';
  } else if (type === 'sent')  { newStatus = 'sent_email';  eventType = 'send_confirmed'; }
  // open / click / soft bounce -> ignored

  const relevant = Boolean(email) && (reason !== '' || newStatus !== '');
  return { json: { relevant, email, reason, newStatus, contactId, eventType } };
});
